    if not cmd:
        return cmd

    # Check for shebang in the first line of the script
    with open(cmd[0], 'r', encoding='utf-8') as file:
        first_line = file.readline().strip()
        if first_line.startswith('#!'):
            # Shebang found, use the specified interpreter
            interpreter = first_line[2:].strip()
            # If the interpreter is a script, find its shebang
            if any(interpreter.endswith(ext) for ext in ('.py', '.pyw')):
                return normalize_cmd((interpreter,) + cmd)
            else:
                return (interpreter,) + cmd[1:]

    return cmd

