@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    import traceback
    import os
    exc_type, exc_value, exc_traceback = e.__class__, e, e.__traceback__
    tb_lines = []
    for i, tb in enumerate(traceback.walk_tb(exc_traceback)):
        if i >= max_level:
            break
        frame, lineno = tb
        filename = frame.f_code.co_filename
        name = frame.f_code.co_name
        path_parts = filename.split(os.path.sep)
        path = os.path.sep.join(path_parts[-max_path_level:])
        tb_lines.append(f'  File "{path}", line {lineno}, in {name}')
        code = linecache.getline(filename, lineno).strip()
        if code:
            tb_lines.append(f'    {code}')
    return f'{exc_type.__module__}.{exc_type.__qualname__}: {exc_value}\n' + '\n'.join(tb_lines)

