def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            result.append(cls)
            for base in cls.__bases__:
                if base in seen:
                    seen.remove(base)
                    result.remove(base)
