def _validate_labels(labels):
    import re
    from collections.abc import Hashable

    # Define regex patterns for keys and values
    key_pattern = r'^[a-zA-Z0-9._-]+$'
    value_pattern = r'^[a-zA-Z0-9._-]+$'

    errors = []

    def _validate_key(key):
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
            return False
        if not re.match(key_pattern, key):
            errors.append({key: f"Label key '{key}' does not match the regex {key_pattern}"})
            return False
        return True

    def _validate_value(value):
        if not isinstance(value, str):
            errors.append({str(value): 'expected string or bytes-like object'})
            return False
        if not re.match(value_pattern, value):
            errors.append({value: f"Label value '{value}' does not match the regex {value_pattern}"})
            return False
        return True

    for key, value in labels.items():
        if not isinstance(key, Hashable):
            errors.append({str(key): 'expected a hashable type'})
            continue
        _validate_key(key)
        if isinstance(value, list):
            for v in value:
                _validate_value(v)
        else:
            _validate_value(value)

    if errors:
        raise ValidationError(errors)

