def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != len(make_value(bin_ for bin_ in hist.bins)[0]):
        raise ValueError("Number of field_names must match the dimension of the result from make_value")

    graph_data = []
    for bin_ in hist.bins:
        bin_value, bin_interval = bin_
        bin_width = bin_interval.right - bin_interval.left
        if get_coordinate == "left":
            x = bin_interval.left
        elif get_coordinate == "right":
            x = bin_interval.right
        elif get_coordinate == "middle":
            x = bin_interval.left + bin_width / 2

        y_values = make_value(bin_value)
        point = (x,) + y_values
        graph_data.append(point)

    if scale is True:
        scale = hist.scale
    elif scale is None:
        scale = "unknown"

    graph = {
        "data": graph_data,
        "scale": scale,
        "field_names": field_names
    }

